.Y') ?: '-'}} - {{$run->ends_at?->format('d.m.Y') ?: '-'}} · {{$course->enrollments->where('course_run_id',$run->id)->count()}} katılımcı</li>@endforeach</ul></div>@endif<div class="card" style="margin-top:20px"><h2>Seanslar</h2>@foreach($course->sessions as $session)<div style="border-top:1px solid #eaecf0;padding:16px 0"><h3>{{$session->title}}</h3><p class="muted">{{$session->starts_at?->format('d.m.Y H:i')}} - {{$session->ends_at?->format('H:i')}}</p>@if($session->meeting_url)<a class="button" href="{{$session->meeting_url}}">Derse katıl</a>@endif @if($session->recording_path)<a class="button secondary" href="{{asset('storage/'.$session->recording_path)}}">Kaydı aç</a>@endif<ul>@foreach($session->materials as $material)<li>{{$material->title}}</li>@endforeach</ul><div style="margin-top:12px"><b>Yoklama</b>@if($session->meeting_status==='not_applicable')<p class="muted" style="margin:4px 0">Yüz yüze seans — katılım yalnızca sizin işaretlemenizle sayılır.</p>@else<p class="muted" style="margin:4px 0">Online seansta katılım, katılımcı odada yeterli süre kalınca otomatik sayılır; bağlantı sorunu olursa buradan da işaretleyebilirsiniz.</p>@endif<ul>@forelse($course->enrollments as $enrollment)@php($attendance = $enrollment->sessionProgress->firstWhere('course_session_id', $session->id))<li>{{$enrollment->user->name}} — @if($attendance?->completed_at)<span class="muted">✓ Katıldı ({{ $attendance->completed_at->format('d.m.Y H:i') }})</span>@else<form method="post" action="{{route('instructor.sessions.attendance',$session)}}" class="inline-form">@csrf<input type="hidden" name="user_id" value="{{$enrollment->user_id}}"><button class="button secondary" type="submit">Katıldı olarak işaretle</button></form>@endif</li>@empty<li class="muted">Katılımcı yok.</li>@endforelse</ul></div></div>@endforeach<h2>Yeni seans planla</h2><p class="muted">Online eğitimlerde toplantı odası ve katılım URL’si otomatik oluşturulur.</p><form method="post" action="{{route('instructor.sessions.store',$course)}}" enctype="multipart/form-data">@csrf<input name="title" placeholder="Seans adı" required><input name="starts_at" type="datetime-local"><input name="ends_at" type="datetime-local"><input name="material" type="file"><button>Seans ve materyal ekle</button></form></div>@endsection
